import cv2 as cv
import numpy as np

def nothing(x):
    pass

cv.namedWindow("Trackbars", cv.WINDOW_NORMAL)
cv.resizeWindow("Trackbars", 400, 400)

cv.createTrackbar("L - H", "Trackbars", 0, 179, nothing)
cv.createTrackbar("U - H", "Trackbars", 179, 179, nothing)
cv.createTrackbar("L - S", "Trackbars", 40, 255, nothing)
cv.createTrackbar("U - S", "Trackbars", 255, 255, nothing)
cv.createTrackbar("L - V", "Trackbars", 40, 255, nothing)
cv.createTrackbar("U - V", "Trackbars", 255, 255, nothing)

cv.createTrackbar("Threshold", "Trackbars", 127, 255, nothing)
cv.createTrackbar("Min Alan", "Trackbars", 500, 5000, nothing)

cap = cv.VideoCapture(0)
kernel = np.ones((5, 5), np.uint8)

while True:
    _, frame = cap.read()
    if frame is None:
        break


    smoothed = cv.medianBlur(frame, 5)
    into_hsv = cv.cvtColor(smoothed, cv.COLOR_BGR2HSV)


    l_h = cv.getTrackbarPos("L - H", "Trackbars")
    u_h = cv.getTrackbarPos("U - H", "Trackbars")
    l_s = cv.getTrackbarPos("L - S", "Trackbars")
    u_s = cv.getTrackbarPos("U - S", "Trackbars")
    l_v = cv.getTrackbarPos("L - V", "Trackbars")
    u_v = cv.getTrackbarPos("U - V", "Trackbars")

    thresh_val = cv.getTrackbarPos("Threshold", "Trackbars")
    min_area = cv.getTrackbarPos("Min Alan", "Trackbars")

    lower = np.array([l_h, l_s, l_v])
    upper = np.array([u_h, u_s, u_v])


    mask = cv.inRange(into_hsv, lower, upper)


    mask = cv.morphologyEx(mask, cv.MORPH_OPEN, kernel, iterations=1)
    mask = cv.morphologyEx(mask, cv.MORPH_CLOSE, kernel, iterations=2)


    _, thresh_mask = cv.threshold(mask, thresh_val, 255, cv.THRESH_BINARY)



    contour_frame = frame.copy()
    contours, _ = cv.findContours(thresh_mask, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE)

    for cnt in contours:
        alan = cv.contourArea(cnt)

        if alan > min_area:

            cv.drawContours(contour_frame, [cnt], -1, (0, 255, 0), 2)


            M = cv.moments(cnt)
            if M["m00"] != 0:
                cX = int(M["m10"] / M["m00"])
                cY = int(M["m01"] / M["m00"])
                cv.putText(contour_frame, f"Alan:{int(alan)}", (cX - 20, cY),
                           cv.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 2)


    color_result = cv.bitwise_and(frame, frame, mask=thresh_mask)


    cv.imshow("1- Threshold & Mask", thresh_mask)
    cv.imshow("2- Renk Sonucu", color_result)
    cv.imshow("3- Kontur Cizimi", contour_frame)

    if cv.waitKey(1) & 0xFF == ord('q'):
        print(f"Sabitlenecek Degerler:\nLower: [{l_h}, {l_s}, {l_v}]\nUpper: [{u_h}, {u_s}, {u_v}]")
        print(f"Onerilen Eşik(Threshold): {thresh_val}, Min Alan: {min_area}")
        break

cap.release()
cv.destroyAllWindows()